/**
 * Development fixtures.
 *
 * These records power "demo mode" (no Supabase configured) and are also the
 * source for `supabase/seed.sql` (generated by `npm run db:seed:generate`).
 *
 * The notes are written as realistic samples for development. They have NOT
 * been independently reviewed by a subject expert, so `reviewer_name` is null
 * and the UI says so. Do not sell them in production without review.
 */
import { estimateReadingMinutes, type StructuredContent } from "@/lib/content/schema";
