export { fixtureSubjects, fixtureTopics };

const subjectBySlug = (slug: string) => {
  const s = fixtureSubjects.find((x) => x.slug === slug);
  if (!s) throw new Error(`Unknown fixture subject ${slug}`);
  return { id: s.id, name: s.name, slug: s.slug };
};
const topicBySlug = (slug: string) => {
  const t = fixtureTopics.find((x) => x.slug === slug);
  if (!t) throw new Error(`Unknown fixture topic ${slug}`);
  return { id: t.id, name: t.name, slug: t.slug };
};

type FixtureSpec = Omit<
  CatalogItem,
  | "subject"
  | "topic"
  | "estimated_reading_minutes"
  | "version_number"
  | "has_pdf"
  | "rating_average"
  | "rating_count"
  | "publication_status"
  | "updated_at"
  | "learning_objectives"
  | "subtitle"
> & { subjectSlug: string; topicSlug: string | null; content: StructuredContent | null };

