const versionId = (itemId: string) => `40000000${itemId.slice(8)}`;

export const fixtureItems: CatalogItem[] = specs.map(({ subjectSlug, topicSlug, content, ...spec }) => ({
  ...spec,
  subtitle: content?.subtitle ?? null,
  subject: subjectBySlug(subjectSlug),
  topic: topicSlug ? topicBySlug(topicSlug) : null,
  publication_status: "published",
  estimated_reading_minutes: content ? estimateReadingMinutes(content) : 0,
  learning_objectives: content?.learningObjectives ?? [],
  version_number: content ? 1 : null,
  // Demo mode has no storage; PDFs are generated on demand in production.
  has_pdf: false,
  rating_average: null,
  rating_count: 0,
  updated_at: spec.published_at ?? "2026-10-10T09:00:00.000Z",
}));

export const fixtureVersions: ContentVersion[] = specs
  .filter((s) => s.content)
  .map((s) => ({
    id: versionId(s.id),
    content_item_id: s.id,
    version_number: 1,
    structured_content: s.content as StructuredContent,
    pdf_storage_path: null,
    change_summary: "Initial sample version",
    created_at: s.published_at ?? "2026-10-10T09:00:00.000Z",
  }));

